sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*
    This BR will trigger at two instances
    1) Whenever bubble is created and then Participant ID is populated, the attributes entered by the user when bubble was crerated will be sent out as a API call
    2) When attributes are updated holding a bubble id and participant ID
	3) Used System Property: x_hsb11_mss_taskiz.taskizeUpdateBubbleOutboundEndPoint
    */
    //participant OutbounRec Creation
    try {
        //Initialized Parameters
        var taskizeCase = current;
        var caseID = current.sys_id;
        var sourceRec = current.sys_id;
        var sourceTable = "x_hsb11_mss_taskiz_mss_taskize_case";
        var bubbleID = current.bubble_id ? current.bubble_id.getDisplayValue() : "";
        var chatLangugae = "en";
        var eventDateTime = current.sys_created_on;
        var topicParam = current.short_description.toString();
        var deadlineParam = current.due_date;
        var scopeParam = "EXTERNAL";
        var filteredoptionalAttributesArray = []; //final array of keys
        var filteredoptionalAttributesArrayVal = []; //final array of values
        var operationsArr = []; //remove or replace
        var eventLayerHeaderParameters = gs.getProperty('x_hsb11_mss_taskiz.taskizeEventHeaderParameters');
        var parseHeader = JSON.parse(eventLayerHeaderParameters);
        var removeOperation = parseHeader.bubblewithAttributesRemoveMethod; //declaring as replace  or remove denamically
        var replaceOperation = parseHeader.bubblewithAttributesReplaceMethod; //declaring as replace  or remove denamically
        var participantID = current.participant_id ? current.participant_id.toString() : "";
        //Initialized Parameters


        //Priority Mapping for Taskize
        PRIORITYMAPPING = {
            1: 'CRITICAL',
            2: 'HIGH',
            3: 'NORMAL',
            4: 'LOW'
        };
        var priorityParam = PRIORITYMAPPING[current.getValue('priority')];
        //Priority Mapping for Taskize

        //comments data

        var journalEntry = current.comments.getJournalEntry(1) ? current.comments.getJournalEntry(1).toString() : "";
        var userQuery = journalEntry ? journalEntry.split(')')[1] : ""; // Use trim() to remove leading/trailing whitespace
        var messageData = userQuery ? userQuery.replaceAll('\n', '') : "";

        //comments data

        var userID;
        var fieldName;
        var currentValue;
        //additional commented if entered by system User
        var auditRec = new GlideRecord("sys_audit");
        auditRec.addEncodedQuery("tablenameSTARTSWITHx_hsb11_mss_taskiz_mss_taskize_case^documentkeySTARTSWITH" + current.sys_id + '^fieldname=comments');
        auditRec.orderByDesc('sys_created_on');
        auditRec.setLimit(1);
        auditRec.query();
        if (auditRec.next()) {
            fieldName = auditRec ? auditRec.fieldname.toString() : "";
            currentValue = auditRec.newvalue;
            userID = auditRec.user;

        }
        //additional commented if entered by system User


        //only for updation of attributes execution the below code

        if ((current.account_number.changes() || current.cash_value.changes() || current.corporate_action_type.changes() || current.currency.changes() || current.cusip.changes() || current.debit_credit.changes() || current.dividend_payment_date.changes() || current.effective_date.changes() || current.event_id.changes() || current.u_event_type.changes() || current.ex_dividend_date.changes() || current.instruction_type.changes() || current.instrument_id.changes() || current.instrument_name.changes() || current.isin.changes() || current.market.changes() || current.market_deadline.changes() || current.notional_value.changes() || current.place_of_trade.changes() || current.price.changes() || current.product_attribute.changes() || current.quantity.changes() || current.record_date.changes() || current.response_deadline.changes() || current.sedol.changes() || current.settlement_amount.changes() || current.settlement_currency.changes() || current.settlement_date.changes() || current.source_record_id.changes() || current.taxability_indicator.changes() || current.trade_date.changes() || current.trade_id.changes() || current.ampid.changes() || current.cob_date.changes() || current.collateral_agreement.changes() || current.collateral_balance.changes() || current.collateral_balance_date.changes() || current.discount_rate.changes() || current.fx_rate.changes() || current.fx_rate_date.changes() || current.haircut.changes() || current.margin_call.changes() || current.margin_call_date.changes() || current.match_id.changes() || current.portfolio_requested.changes() || current.trade_confirmation_reference.changes() || current.trader.changes() || current.triresolve_ref.changes() || current.hsbc_market.changes() || current.hsbc_product.changes() || current.hsbc_entity.changes() || current.market_country.changes() || current.exchange.changes())) {

            //Payload Keys as per taskize
            var optionalAttributesArray = [
                'attributes.accountNumber',
                'attributes.cashValue',
                'attributes.corpActionType',
                'attributes.currency',
                'attributes.cusip',
                'attributes.debitCredit', //notthere
                'attributes.divPayDate',
                'attributes.effectiveDate',
                'attributes.eventId',
                'attributes.corpActionEventType',
                'attributes.exDivDate',
                'attributes.instructionType', //not there
                'attributes.instrumentIdentifier',
                'attributes.instrumentName',
                'attributes.isin',
                'attributes.market',
                'attributes.marketDeadline',
                'attributes.notionalValue',
                'attributes.placeOfTrade',
                'attributes.price',
                'attributes.product',
                'attributes.quantity',
                'attributes.recordDate',
                'attributes.responseDeadline',
                'attributes.sedol',
                'attributes.settlementAmount',
                'attributes.settlementCurrency',
                'attributes.settlementDate',
                'attributes.sourceRecordId',
                'attributes.taxIndicator',
                'attributes.tradeDate',
                'attributes.tradeIdentifier',
                'attributes.ampId',
                'attributes.cobDate',
                'attributes.collateralAgreement',
                'attributes.collateralBalance',
                'attributes.collateralBalanceDate',
                'attributes.discountRate',
                'attributes.fxRate',
                'attributes.fxRateDate',
                'attributes.haircut',
                'attributes.marginCall',
                'attributes.marginCallDate',
                'attributes.matchId',
                'attributes.portfolioRequested',
                'attributes.tradeConfirmationRef',
                'attributes.trader',
                'attributes.triResolveRef',
                'attributes.hsbcMarket',
                'attributes.hsbcProduct',
                'attributes.hsbcEntity',
				'attributes.marketCountry',
				'attributes.exchange'
            ];

            //Current Values of array for comparison
            var currentOptionalAttributesArrayVal = [
                current.account_number ? current.account_number.getDisplayValue() : "",
                current.cash_value ? current.cash_value.getDisplayValue().replaceAll(',', '') : "",
                current.corporate_action_type ? current.corporate_action_type.getDisplayValue() : "",
                current.currency ? current.currency.getDisplayValue() : "",
                current.cusip ? current.cusip.getDisplayValue() : "",
                current.debit_credit ? current.debit_credit.getDisplayValue() : "",
                current.dividend_payment_date ? current.dividend_payment_date.getDisplayValue() : "",
                current.effective_date ? current.effective_date.getDisplayValue() : "",
                current.event_id ? current.event_id.getDisplayValue() : "",
                current.u_event_type ? current.u_event_type.getDisplayValue() : "",
                current.ex_dividend_date ? current.ex_dividend_date.getDisplayValue() : "",
                current.instruction_type ? current.instruction_type.getDisplayValue() : "",
                current.instrument_id ? current.instrument_id.getDisplayValue() : "",
                current.instrument_name ? current.instrument_name.getDisplayValue() : "",
                current.isin ? current.isin.getDisplayValue() : "",
                current.market ? current.market.getDisplayValue() : "",
                current.market_deadline ? current.market_deadline.getDisplayValue() : "",
                current.notional_value ? current.notional_value.getDisplayValue().replaceAll(',', '') : "",
                current.place_of_trade ? current.place_of_trade.getDisplayValue() : "",
                current.price ? current.price.getDisplayValue().replaceAll(',', '') : "",
                current.product_attribute ? current.product_attribute.getDisplayValue() : "",
                current.quantity ? current.quantity.getDisplayValue() : "",
                current.record_date ? current.record_date.getDisplayValue() : "",
                current.response_deadline ? current.response_deadline.getDisplayValue() : "",
                current.sedol ? current.sedol.getDisplayValue() : "",
                current.settlement_amount ? current.settlement_amount.getDisplayValue().replaceAll(',', '') : "",
                current.settlement_currency ? current.settlement_currency.getDisplayValue() : "",
                current.settlement_date ? current.settlement_date.getDisplayValue() : "",
                current.source_record_id ? current.source_record_id.getDisplayValue() : "",
                current.taxability_indicator ? current.taxability_indicator.getDisplayValue() : "",
                current.trade_date ? current.trade_date.getDisplayValue() : "",
                current.trade_id ? current.trade_id.getDisplayValue() : "",
                current.ampid ? current.ampid.getDisplayValue() : "",
                current.cob_date ? current.cob_date.getDisplayValue() : "",
                current.collateral_agreement ? current.collateral_agreement.getDisplayValue() : "",
                current.collateral_balance ? current.collateral_balance.getDisplayValue().replaceAll(',', '') : "",
                current.collateral_balance_date ? current.collateral_balance_date.getDisplayValue() : "",
                current.discount_rate ? current.discount_rate.getDisplayValue().replaceAll(',', '') : "",
                current.fx_rate ? current.fx_rate.getDisplayValue().replaceAll(',', '') : "",
                current.fx_rate_date ? current.fx_rate_date.getDisplayValue() : "",
                current.haircut ? current.haircut.getDisplayValue() : "",
                current.margin_call ? current.margin_call.getDisplayValue().replaceAll(',', '') : "",
                current.margin_call_date ? current.margin_call_date.getDisplayValue() : "",
                current.match_id ? current.match_id.getDisplayValue() : "",
                current.portfolio_requested ? current.portfolio_requested.getDisplayValue() : "",
                current.trade_confirmation_reference ? current.trade_confirmation_reference.getDisplayValue() : "",
                current.trader ? current.trader.getDisplayValue() : "",
                current.triresolve_ref ? current.triresolve_ref.getDisplayValue() : "",
                current.hsbc_market ? current.hsbc_market.getDisplayValue() : "",
                current.hsbc_product ? current.hsbc_product.getDisplayValue() : "",
                current.hsbc_entity ? current.hsbc_entity.getDisplayValue() : "",
				current.market_country ? current.market_country :"",
				current.exchange? current.exchange.value :""

            ];

            //Previous Values of array for comparison
            var previousOptionalAttributesArrayVal = [
                previous.account_number ? previous.account_number.getDisplayValue() : "",
                previous.cash_value ? previous.cash_value.getDisplayValue().replaceAll(',', '') : "",
                previous.corporate_action_type ? previous.corporate_action_type.getDisplayValue() : "",
                previous.currency ? previous.currency.getDisplayValue() : "",
                previous.cusip ? previous.cusip.getDisplayValue() : "",
                previous.debit_credit ? previous.debit_credit.getDisplayValue() : "",
                previous.dividend_payment_date ? previous.dividend_payment_date.getDisplayValue() : "",
                previous.effective_date ? previous.effective_date.getDisplayValue() : "",
                previous.event_id ? previous.event_id.getDisplayValue() : "",
                previous.u_event_type ? previous.u_event_type.getDisplayValue() : "",
                previous.ex_dividend_date ? previous.ex_dividend_date.getDisplayValue() : "",
                previous.instruction_type ? previous.instruction_type.getDisplayValue() : "",
                previous.instrument_id ? previous.instrument_id.getDisplayValue() : "",
                previous.instrument_name ? previous.instrument_name.getDisplayValue() : "",
                previous.isin ? previous.isin.getDisplayValue() : "",
                previous.market ? previous.market.getDisplayValue() : "",
                previous.market_deadline ? previous.market_deadline.getDisplayValue() : "",
                previous.notional_value ? previous.notional_value.getDisplayValue().replaceAll(',', '') : "",
                previous.place_of_trade ? previous.place_of_trade.getDisplayValue() : "",
                previous.price ? previous.price.getDisplayValue().replaceAll(',', '') : "",
                previous.product_attribute ? previous.product_attribute.getDisplayValue() : "",
                previous.quantity ? previous.quantity.getDisplayValue() : "",
                previous.record_date ? previous.record_date.getDisplayValue() : "",
                previous.response_deadline ? previous.response_deadline.getDisplayValue() : "",
                previous.sedol ? previous.sedol.getDisplayValue() : "",
                previous.settlement_amount ? previous.settlement_amount.getDisplayValue().replaceAll(',', '') : "",
                previous.settlement_currency ? previous.settlement_currency.getDisplayValue() : "",
                previous.settlement_date ? previous.settlement_date.getDisplayValue() : "",
                previous.source_record_id ? previous.source_record_id.getDisplayValue() : "",
                previous.taxability_indicator ? previous.taxability_indicator.getDisplayValue() : "",
                previous.trade_date ? previous.trade_date.getDisplayValue() : "",
                previous.trade_id ? previous.trade_id.getDisplayValue() : "",
                previous.ampid ? previous.ampid.getDisplayValue() : "",
                previous.cob_date ? previous.cob_date.getDisplayValue() : "",
                previous.collateral_agreement ? previous.collateral_agreement.getDisplayValue() : "",
                previous.collateral_balance ? previous.collateral_balance.getDisplayValue().replaceAll(',', '') : "",
                previous.collateral_balance_date ? previous.collateral_balance_date.getDisplayValue() : "",
                previous.discount_rate ? previous.discount_rate.getDisplayValue().replaceAll(',', '') : "",
                previous.fx_rate ? previous.fx_rate.getDisplayValue().replaceAll(',', '') : "",
                previous.fx_rate_date ? previous.fx_rate_date.getDisplayValue() : "",
                previous.haircut ? previous.haircut.getDisplayValue() : "",
                previous.margin_call ? previous.margin_call.getDisplayValue().replaceAll(',', '') : "",
                previous.margin_call_date ? previous.margin_call_date.getDisplayValue() : "",
                previous.match_id ? previous.match_id.getDisplayValue() : "",
                previous.portfolio_requested ? previous.portfolio_requested.getDisplayValue() : "",
                previous.trade_confirmation_reference ? previous.trade_confirmation_reference.getDisplayValue() : "",
                previous.trader ? previous.trader.getDisplayValue() : "",
                previous.triresolve_ref ? previous.triresolve_ref.getDisplayValue() : "",
                previous.hsbc_market ? previous.hsbc_market.getDisplayValue() : "",
                previous.hsbc_product ? previous.hsbc_product.getDisplayValue() : "",
                previous.hsbc_entity ? previous.hsbc_entity.getDisplayValue() : "",
				previous.market_country ? previous.market_country :"",
				previous.exchange? previous.exchange.value :""

            ];

            //Picking up Attributes only those have changed
            for (var i = 0; i < optionalAttributesArray.length; i++) {

                //when any attribute changes holding bubble ID and participant ID
                if (currentOptionalAttributesArrayVal[i] != previousOptionalAttributesArrayVal[i]) { //generic update
                    filteredoptionalAttributesArray.push(optionalAttributesArray[i] + "");
                    filteredoptionalAttributesArrayVal.push(currentOptionalAttributesArrayVal[i] + "");
                    if (currentOptionalAttributesArrayVal[i] == '') {
                        operationsArr.push(removeOperation.toString()); //remove
                    } else {
                        operationsArr.push(replaceOperation.toString()); // replace
                    }
                    //declaring as replace  or remove denamically
                }

            }


            if (filteredoptionalAttributesArrayVal.length > 0 && (current.participant_id != '') && (current.sys_updated_by.indexOf('system') == -1)) { //chacke if actually any attribues are changed
                //Trigger the outbound Call to send changed attributes
                new x_hsb11_mss_taskiz.MSSTaskizeUtils().patchBubbleWithAttributes(caseID, bubbleID, participantID, eventDateTime, topicParam, filteredoptionalAttributesArray, filteredoptionalAttributesArrayVal, operationsArr, sourceRec, sourceTable);
            }



        }



        //independent if user tried to enter a commnet and changes attribute at same instane this will trigger
        if (((previous.participant_id == '') && (current.participant_id != '') && (messageData != '') && (current.draft_comments != "")) || ((current.comments.getJournalEntry(1) != null) && (current.participant_id != '') && (previous.participant_id != '') && messageData != '' && (fieldName == 'comments') && (userID.indexOf('system') == -1) && (current.comments.changes()))) {


            new x_hsb11_mss_taskiz.MSSTaskizeUtils().createOutboundContentAPI(caseID, bubbleID, messageData, sourceRec, sourceTable, eventDateTime, participantID);
            //log first & last response time
            var userName = gs.getUser().getDisplayName();
            if (userName != 'system') {
                var now = new GlideDateTime();
                if (gs.nil(previous.first_response_time)) {
                    current.first_response_time = now;
                }
                current.last_response_time = now;
                //Taskize-134
                var ragValue = calculateAndUpdateRAG(current);
                if (ragValue) {
                    current.rag = ragValue;
                } //***Taskize-134 ends
                current.update();
            }

        } else {
            //do nothing
        }


        if ((previous.participant_id == '') && (current.participant_id != '')) {
            var updateCase = new GlideRecord("x_hsb11_mss_taskiz_mss_taskize_case");
            updateCase.get(current.sys_id);
            updateCase.setValue('draft_comments', "");
            updateCase.update();
        }



    } catch (ex) {
        gs.info("Error from BR - Taskize - Create Outbound Payload - Participant Loop" + ex);
    }

    ///TASKIZE-134
    function calculateAndUpdateRAG(record) {
        try {
            var now = new GlideDateTime();
            var createdDateTime = new GlideDateTime(record.sys_created_on);
            var responseDateTime = record.last_response_time ? new GlideDateTime(record.last_response_time) : now;

            var diffHours = (responseDateTime.getNumericValue() - createdDateTime.getNumericValue()) / (1000 * 60 * 60);

            var ragValue = diffHours <= 2 ? '<2' : diffHours <= 5 ? '2-5' : '>5';

            return ragValue;
        } catch (e) {
            gs.error(`Error in calculateAndUpdateRAG: ${e.message}`);
            return null;
        }
    }
    ///***TASKIZE-134 ends */




})(current, previous);
